using System.Text;
using System.Text.RegularExpressions;

namespace AnimStudio.Application.Publishing;

/// <summary>Result of normalizing YouTube metadata for automatic policy compliance during content creation.</summary>
public sealed record SanitizedYouTubePackaging(
    string Title,
    string Description,
    IReadOnlyList<string> Tags,
    string? PinnedComment,
    bool MadeForKids);

/// <summary>
/// Automatically enforces YouTube Partner Program, Metadata Spam, and AdSense content packaging policies
/// whenever titles, descriptions, hashtags, and tags are generated by templates or AI — so creators
/// never have to fix policy violations manually before publishing or scheduling.
/// </summary>
public static partial class YouTubePolicyComplianceSanitizer
{
    private const int RecommendedMinHashtags = 3;
    private const int RecommendedMaxHashtags = 8;
    private const int MaxDescriptionUrlLines = 4;

    private static readonly Regex EngagementBaitRegex = MyBaitRegex();
    private static readonly Regex ShortenerUrlRegex = MyShortenerRegex();
    private static readonly Regex HashtagRegex = MyHashtagRegex();
    private static readonly Regex WhitespaceRegex = MyWhitespaceRegex();
    private static readonly Regex MultiBlankLinesRegex = MyMultiBlankLinesRegex();
    private static readonly Regex DisallowedYouTubeCharsRegex = MyDisallowedCharsRegex();
    private static readonly Regex InternalTokenLeakRegex = MyInternalTokenLeakRegex();
    private static readonly Regex UrlInLineRegex = MyUrlInLineRegex();

    public static SanitizedYouTubePackaging Sanitize(
        string? rawTitle,
        string? rawDescription,
        IEnumerable<string>? rawTags,
        string? rawPinnedComment,
        string? fallbackTopicTitle = null,
        string? primaryDestinationUrl = null,
        bool? requestedMadeForKids = null,
        bool isShort = false,
        string language = "hi")
    {
        var cleanTitle = CleanTitle(rawTitle, fallbackTopicTitle);
        var cleanTags = CleanTags(rawTags, cleanTitle, isShort, language);
        var cleanDesc = CleanDescription(rawDescription, cleanTitle, cleanTags, primaryDestinationUrl, language);
        var cleanComment = CleanPinnedComment(rawPinnedComment, primaryDestinationUrl, language);

        // General comedy, educational Panchang, Rashifal, history & quiz content must not declare Made-for-Kids false positives.
        var madeForKids = requestedMadeForKids ?? false;

        return new SanitizedYouTubePackaging(cleanTitle, cleanDesc, cleanTags, cleanComment, madeForKids);
    }

    public static string CleanTitle(string? rawTitle, string? fallbackTitle = null)
    {
        var candidate = StripPolicyHazards(rawTitle ?? string.Empty);
        candidate = WhitespaceRegex.Replace(candidate, " ").Trim(' ', '-', '|', ':', ',');
        if (candidate.Length < 3 && !string.IsNullOrWhiteSpace(fallbackTitle))
            candidate = StripPolicyHazards(fallbackTitle);
        if (candidate.Length < 3)
            candidate = "Original Studio Update";

        // Soften shouty all-caps ASCII titles while preserving normal acronyms (AI, EP, GK, USA).
        candidate = NormalizeShoutyWords(candidate);
        return TrimToWordBoundary(candidate, YouTubePublishValidator.MaxTitleLength);
    }

    public static IReadOnlyList<string> CleanTags(
        IEnumerable<string>? rawTags,
        string cleanTitle,
        bool isShort,
        string language)
    {
        var result = new List<string>();
        var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        void TryAdd(string? raw)
        {
            if (string.IsNullOrWhiteSpace(raw)) return;
            var cleaned = StripPolicyHazards(raw).Replace("#", string.Empty, StringComparison.Ordinal).Replace(",", " ", StringComparison.Ordinal);
            cleaned = WhitespaceRegex.Replace(cleaned, " ").Trim(' ', '-', '|', ':');
            if (cleaned.Length < 2 || cleaned.Length > 45 || !seen.Add(cleaned)) return;

            var candidate = new List<string>(result) { cleaned };
            if (candidate.Count <= 30 && YouTubePublishValidator.TagsLength(candidate) <= YouTubePublishValidator.MaxTagsLength)
                result.Add(cleaned);
        }

        if (rawTags is not null)
        {
            foreach (var tag in rawTags) TryAdd(tag);
        }

        if (isShort) TryAdd("Shorts");
        TryAdd(language.Equals("en", StringComparison.OrdinalIgnoreCase) ? "YouTube Shorts" : "Hindi Shorts");

        if (result.Count < 3)
        {
            foreach (var token in cleanTitle.Split([' ', '|', ':', '-', ',', '•'], StringSplitOptions.RemoveEmptyEntries))
            {
                if (token.Length >= 4) TryAdd(token);
                if (result.Count >= 6) break;
            }
        }

        return result;
    }

    public static string CleanDescription(
        string? rawDescription,
        string cleanTitle,
        IReadOnlyList<string> cleanTags,
        string? primaryDestinationUrl,
        string language)
    {
        var cleaned = StripPolicyHazards(rawDescription ?? string.Empty);

        // Remove any excess trailing hashtag block so we keep 3..8 clean hashtags (strictly <= 15 limit).
        var extractedHashtags = new List<string>();
        var seenTags = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (Match m in HashtagRegex.Matches(cleaned))
        {
            var tag = m.Value.Trim();
            if (tag.Length > 2 && tag.Length <= 32 && seenTags.Add(tag))
                extractedHashtags.Add(tag);
        }

        if (extractedHashtags.Count > RecommendedMaxHashtags)
        {
            // Strip existing hashtags from body and re-append a clean curated 3..8 set at the footer.
            cleaned = HashtagRegex.Replace(cleaned, string.Empty);
        }

        cleaned = NormalizeUrlsToRootDomain(cleaned);
        cleaned = MultiBlankLinesRegex.Replace(cleaned.Trim(), "\n\n");
        if (cleaned.Length < 25)
        {
            var fallbackSummary = language.Equals("en", StringComparison.OrdinalIgnoreCase)
                ? $"{cleanTitle} — Original animated episode produced cleanly in AnimStudio."
                : $"{cleanTitle} — पूरी जानकारी, मूल प्रस्तुति और उपयोगी विवरण देखें।";
            cleaned = string.IsNullOrWhiteSpace(cleaned) ? fallbackSummary : $"{fallbackSummary}\n\n{cleaned}";
        }

        var cleanPrimaryUrl = ToRootDomainUrl(primaryDestinationUrl);
        if (!string.IsNullOrWhiteSpace(cleanPrimaryUrl)
            && !ContainsRootUrl(cleaned, cleanPrimaryUrl))
        {
            var label = language.Equals("en", StringComparison.OrdinalIgnoreCase)
                ? "🔗 Official Portal"
                : "🌐 आधिकारिक पोर्टल";
            cleaned = $"{cleaned}\n\n{label}: {cleanPrimaryUrl}";
        }

        cleaned = DeduplicateExcessUrlLines(cleaned, cleanPrimaryUrl);

        if (extractedHashtags.Count > RecommendedMaxHashtags || extractedHashtags.Count == 0)
        {
            var curated = extractedHashtags.Count > 0
                ? extractedHashtags.Take(RecommendedMaxHashtags).ToList()
                : BuildHashtagsFromTags(cleanTags, RecommendedMinHashtags, RecommendedMaxHashtags);

            if (curated.Count > 0)
                cleaned = $"{cleaned}\n\n{string.Join(" ", curated)}";
        }

        if (Encoding.UTF8.GetByteCount(cleaned) > YouTubePublishValidator.MaxDescriptionBytes)
            cleaned = TrimUtf8ToBytes(cleaned, YouTubePublishValidator.MaxDescriptionBytes - 64);

        return cleaned.Trim();
    }

    public static string? CleanPinnedComment(string? rawPinnedComment, string? primaryDestinationUrl, string language)
    {
        if (string.IsNullOrWhiteSpace(rawPinnedComment)) return rawPinnedComment;
        var clean = MultiBlankLinesRegex.Replace(NormalizeUrlsToRootDomain(StripPolicyHazards(rawPinnedComment)).Trim(), "\n\n");
        var cleanPrimaryUrl = ToRootDomainUrl(primaryDestinationUrl);
        if (!string.IsNullOrWhiteSpace(cleanPrimaryUrl)
            && !ContainsRootUrl(clean, cleanPrimaryUrl))
        {
            var cta = language.Equals("en", StringComparison.OrdinalIgnoreCase)
                ? $"Explore more: {cleanPrimaryUrl}"
                : $"पूरी जानकारी यहाँ देखें: {cleanPrimaryUrl}";
            clean = string.IsNullOrWhiteSpace(clean) ? cta : $"{clean}\n{cta}";
        }
        return clean.Length > 2000 ? TrimToWordBoundary(clean, 2000) : clean;
    }

    /// <summary>
    /// Trims query strings, fragments, and sub-paths so YouTube descriptions and pinned comments
    /// only publish clean root domain/subdomain links (e.g. <c>https://*.keshavsingh.in</c>).
    /// </summary>
    public static string ToRootDomainUrl(string? url)
    {
        var trimmed = url?.Trim();
        if (string.IsNullOrWhiteSpace(trimmed)) return string.Empty;
        if (Uri.TryCreate(trimmed, UriKind.Absolute, out var uri)
            && (uri.Scheme == Uri.UriSchemeHttp || uri.Scheme == Uri.UriSchemeHttps)
            && !string.IsNullOrWhiteSpace(uri.Host))
        {
            return uri.GetLeftPart(UriPartial.Authority).TrimEnd('/');
        }
        var qIdx = trimmed.IndexOf('?');
        return (qIdx >= 0 ? trimmed[..qIdx] : trimmed).TrimEnd('/');
    }

    public static string NormalizeUrlsToRootDomain(string text)
    {
        if (string.IsNullOrWhiteSpace(text)) return string.Empty;
        return UrlInLineRegex.Replace(text, match =>
        {
            var token = match.Value;
            var trimmed = token.TrimEnd('.', ',', ';', ')', '!');
            var suffix = token[trimmed.Length..];
            var root = ToRootDomainUrl(trimmed);
            return string.IsNullOrWhiteSpace(root) ? token : root + suffix;
        });
    }

    /// <summary>
    /// Formats up to <paramref name="maxCount"/> unique root-domain portal lines (e.g.
    /// <c>🌐 Keshav Hub: https://keshavsingh.in</c>) deduplicated by domain/subdomain URL.
    /// </summary>
    public static IReadOnlyList<string> FormatRootPortalLines(
        IEnumerable<(string Label, string? Url)> links,
        int maxCount = MaxDescriptionUrlLines,
        string primaryPrefix = "🌐 ",
        string secondaryPrefix = "• ")
    {
        var seenRoots = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var lines = new List<string>(maxCount);
        foreach (var (label, url) in links)
        {
            var rootUrl = ToRootDomainUrl(url);
            if (string.IsNullOrWhiteSpace(rootUrl) || !seenRoots.Add(rootUrl)) continue;
            var prefix = lines.Count == 0 ? primaryPrefix : secondaryPrefix;
            var cleanLabel = string.IsNullOrWhiteSpace(label) ? rootUrl : label.Trim();
            lines.Add($"{prefix}{cleanLabel}: {rootUrl}");
            if (lines.Count >= maxCount) break;
        }
        return lines;
    }

    private static bool ContainsRootUrl(string text, string rootUrl) =>
        UrlInLineRegex.Matches(text).Any(m =>
            string.Equals(ToRootDomainUrl(m.Value.TrimEnd('.', ',', ';', ')', '!')), rootUrl, StringComparison.OrdinalIgnoreCase));

    private static List<string> BuildHashtagsFromTags(IReadOnlyList<string> tags, int min, int max)
    {
        var list = new List<string>();
        var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var raw in tags)
        {
            if (list.Count >= max) break;
            var token = new string(raw.Where(c => char.IsLetterOrDigit(c) || char.GetUnicodeCategory(c) == System.Globalization.UnicodeCategory.NonSpacingMark).ToArray());
            if (token.Length < 2 || token.Length > 28) continue;
            var h = "#" + token;
            if (seen.Add(h)) list.Add(h);
        }

        if (list.Count < min)
        {
            foreach (var fallback in new[] { "#Shorts", "#YouTubeShorts", "#DailyUpdate" })
            {
                if (seen.Add(fallback)) list.Add(fallback);
                if (list.Count >= min) break;
            }
        }
        return list;
    }

    private static string StripPolicyHazards(string text)
    {
        if (string.IsNullOrWhiteSpace(text)) return string.Empty;
        var clean = DisallowedYouTubeCharsRegex.Replace(text, string.Empty);
        clean = InternalTokenLeakRegex.Replace(clean, string.Empty);
        clean = EngagementBaitRegex.Replace(clean, string.Empty);
        clean = ShortenerUrlRegex.Replace(clean, string.Empty);
        return clean;
    }

    private static string DeduplicateExcessUrlLines(string text, string? primaryDestinationUrl)
    {
        var seenRoots = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var lines = text.Split('\n');
        var keptLines = new List<string>(lines.Length);
        var cleanPrimary = ToRootDomainUrl(primaryDestinationUrl);
        foreach (var rawLine in lines)
        {
            var line = rawLine.TrimEnd('\r');
            var urlMatches = UrlInLineRegex.Matches(line);
            if (urlMatches.Count == 0)
            {
                keptLines.Add(line);
                continue;
            }

            var lineRoots = urlMatches
                .Select(m => ToRootDomainUrl(m.Value.TrimEnd('.', ',', ';', ')', '!')))
                .Where(u => !string.IsNullOrWhiteSpace(u))
                .ToList();
            if (lineRoots.Count == 0) continue;

            var isPrimary = !string.IsNullOrWhiteSpace(cleanPrimary)
                && lineRoots.Any(u => string.Equals(u, cleanPrimary, StringComparison.OrdinalIgnoreCase));
            var allAlreadySeen = lineRoots.All(seenRoots.Contains);
            if (allAlreadySeen) continue;

            if (isPrimary || seenRoots.Count < MaxDescriptionUrlLines)
            {
                foreach (var u in lineRoots) seenRoots.Add(u);
                keptLines.Add(line);
            }
        }
        return MultiBlankLinesRegex.Replace(string.Join('\n', keptLines).Trim(), "\n\n");
    }

    private static string NormalizeShoutyWords(string text)
    {
        var words = text.Split(' ', StringSplitOptions.RemoveEmptyEntries);
        for (var i = 0; i < words.Length; i++)
        {
            var w = words[i];
            if (w.Length >= 5 && w.Any(char.IsAsciiLetter) && w.Where(char.IsAsciiLetter).All(char.IsUpper))
                words[i] = char.ToUpperInvariant(w[0]) + w[1..].ToLowerInvariant();
        }
        return string.Join(' ', words);
    }

    private static string TrimToWordBoundary(string value, int maxLen)
    {
        if (value.Length <= maxLen) return value;
        var slice = value[..maxLen];
        var lastSpace = slice.LastIndexOf(' ');
        return (lastSpace >= maxLen / 2 ? slice[..lastSpace] : slice).TrimEnd(' ', '-', '|', ':', ',');
    }

    private static string TrimUtf8ToBytes(string value, int maxBytes)
    {
        var sb = new StringBuilder(value.Length);
        var bytes = 0;
        foreach (var rune in value.EnumerateRunes())
        {
            var size = rune.Utf8SequenceLength;
            if (bytes + size > maxBytes) break;
            sb.Append(rune);
            bytes += size;
        }
        return sb.ToString().TrimEnd();
    }

    [GeneratedRegex(@"\b(sub4sub|sub\s*4\s*sub|sub\s*for\s*sub|subscribe\s*back|watch4watch|watch\s*4\s*watch|buy\s*views|free\s*views|like4like|like\s*for\s*like)\b", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant)]
    private static partial Regex MyBaitRegex();

    [GeneratedRegex(@"https?://(?:bit\.ly|tinyurl\.com|goo\.gl|t\.co)/\S+", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant)]
    private static partial Regex MyShortenerRegex();

    [GeneratedRegex(@"#[^\s#]+", RegexOptions.CultureInvariant)]
    private static partial Regex MyHashtagRegex();

    [GeneratedRegex(@"[ \t]{2,}", RegexOptions.CultureInvariant)]
    private static partial Regex MyWhitespaceRegex();

    [GeneratedRegex(@"\n{3,}", RegexOptions.CultureInvariant)]
    private static partial Regex MyMultiBlankLinesRegex();

    [GeneratedRegex(@"[<>]|[\x00-\x08\x0B\x0C\x0E-\x1F]", RegexOptions.CultureInvariant)]
    private static partial Regex MyDisallowedCharsRegex();

    [GeneratedRegex(@"\b(?:DesiKhadiSitcom|KhadiBhasha|TuTadak|RoastAndTwist|GlobalSlapstick|FamilyClean|TankSeries|FunnyComedy)\b", RegexOptions.CultureInvariant)]
    private static partial Regex MyInternalTokenLeakRegex();

    [GeneratedRegex(@"https?://\S+", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant)]
    private static partial Regex MyUrlInLineRegex();
}
